function icon(name,size=16){return `<svg class="icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;}
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rupiah=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n).replace('Rp ','Rp ');
const num=n=>new Intl.NumberFormat('id-ID').format(n);
const short=n=>n>=1000000?`${(n/1000000).toFixed(1).replace('.',',')} jt`:n>=1000?`${Math.round(n/1000)} rb`:num(n);
const dateLabel=d=>new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short'}).format(new Date(d+'T00:00:00Z'));
const storageKey='laras-demo-v1';
let saved=null;try{saved=JSON.parse(localStorage.getItem(storageKey));}catch{}
const state={orders:Array.isArray(saved?.orders)?saved.orders:seedOrders(),files:Array.isArray(saved?.files)?saved.files:initialFiles.map(f=>({...f})),history:saved?.history||[],preferences:saved?.preferences||{daily:true,stock:true,production:true},resolved:saved?.resolved||[],route:location.hash.replace('#','')||'overview',period:'21',chart:'revenue',filter:'all',query:'',chat:[],modal:null,upload:null,mobile:false};
const titles={overview:'Dashboard',sales:'Penjualan',inventory:'Persediaan',production:'Produksi',sources:'Sumber Data',insights:'Proaktif',chat:'Chat with Data',records:'Data',settings:'Pengaturan'};
const dashboardRoutes=['overview','records','sales','inventory','production'];
state.cloud=false;state.backend=null;state.backendError='';state.dashboard=null;state.workspaceName='Nusa Studio';state.chatBusy=false;
state.insightFilter='open';state.chatContext=null;state.pendingQuestion=null;
function persist(){if(state.cloud)return;try{localStorage.setItem(storageKey,JSON.stringify({orders:state.orders,files:state.files,history:state.history,preferences:state.preferences,resolved:state.resolved}));}catch{toast('Penyimpanan peramban penuh. Perubahan sesi ini belum tersimpan.',true);}}
function filteredOrders(){const latest=state.orders.reduce((d,r)=>r.date>d?r.date:d,'0001-01-01');const start=new Date(latest+'T00:00:00Z');start.setUTCDate(start.getUTCDate()-(Number(state.period)-1));const from=start.toISOString().slice(0,10);return state.orders.filter(r=>r.date>=from&&r.date<=latest);}
function periodLabel(){const rows=filteredOrders();if(!rows.length)return 'Belum ada data';const dates=rows.map(r=>r.date).sort();return `${dateLabel(dates[0])} – ${dateLabel(dates.at(-1))} ${dates.at(-1).slice(0,4)}`;}
function statusLabel(label){return ({'Perlu review':'Perlu ditinjau','Quality check':'Pemeriksaan mutu'})[label]||label;}
function badge(label,tone=''){label=statusLabel(label);return `<span class="badge ${tone}">${escape(label)}</span>`;}
function navLink(route,label,i,count='') {
  const active=state.route===route||(route==='overview'&&dashboardRoutes.includes(state.route));
  return `<a href="#${route}" class="nav-link ${active?'active':''}" ${active?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${count!==''?`<span class="count">${count}</span>`:''}</a>`;
}
function dashboardTabs() {
 const dynamic=dashboard.active();
 const available=dynamic?[['overview','Ringkasan'],['records','Data'],...([['sales','Penjualan'],['inventory','Persediaan'],['production','Produksi']].filter(([route])=>(state.cloud?state.datasets||[]:[state.adaptive?.dataset]).some(d=>d?.domain===route)))]:[['overview','Ringkasan'],['sales','Penjualan'],['inventory','Persediaan'],['production','Produksi']];
 return `<nav class="dashboard-tabs" aria-label="Bagian dashboard">${available.map(([route,label])=>`<a href="#${route}" ${state.route===route?'class="active" aria-current="page"':''}>${label}</a>`).join('')}</nav>`;
}
function render() {
  document.title=`${titles[state.route]||'Dashboard'} — Laras`;
  const openCount=pendingInsights().length;
  document.getElementById('app').innerHTML=`<div class="app-shell">
    <div class="mobile-scrim ${state.mobile?'open':''}" data-action="close-menu"></div>
    <aside class="sidebar sidebar-simple" aria-label="Navigasi utama">
      <a class="brand" href="#overview"><img src="./favicon.svg" alt=""><span>Laras</span><sup>BETA</sup></a>
      <button class="workspace-switch" data-action="workspace"><span class="workspace-avatar">${escape(state.workspaceName.slice(0,1))}</span><span><strong>${escape(state.workspaceName)}</strong><small>Ruang kerja bisnis</small></span>${icon('down',13)}</button>
      <nav class="primary-navigation" id="primary-navigation" aria-label="Menu ruang kerja">${navLink('overview','Dashboard','overview')}${navLink('insights','Proaktif','spark',openCount)}${navLink('chat','Chat with Data','chat')}${navLink('sources','Sumber Data','data')}</nav>
      <button class="sidebar-upload" data-action="upload">${icon('plus',16)}Tambah data</button>
      <div class="sidebar-bottom"><div class="sidebar-status"><i class="live-dot"></i>${state.cloud?'Supabase':'Mode demo'}<small>${state.cloud?(state.backendError?'Sinkronisasi tertunda':'Tersinkron'):'Data lokal'}</small></div><a href="#settings" class="workspace-settings ${state.route==='settings'?'active':''}" ${state.route==='settings'?'aria-current="page"':''}>${icon('settings',16)}Pengaturan</a><div class="profile"><span class="profile-avatar">${escape(state.workspaceName.split(' ').map(p=>p[0]).join('').slice(0,2))}</span><span><strong>${escape(state.workspaceName)}</strong><small>${dashboard.active()?escape(state.adaptive?.context||'Data bisnis'):'Mode dan gaya hidup'}</small></span><button class="icon-button" data-action="about" aria-label="Tentang ruang kerja">${icon('more',17)}</button></div></div>
    </aside>
    <div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" data-action="menu" aria-label="Buka navigasi" aria-expanded="${state.mobile}" aria-controls="primary-navigation">${icon('menu',19)}</button><span>${escape(state.workspaceName)}</span>${icon('chevron',12)}<strong>${titles[state.route]||'Dashboard'}</strong></div><div class="topbar-right"><button class="search-trigger" data-action="search" aria-label="Cari di ruang kerja">${icon('search',16)}<span>Cari...</span><kbd>⌘ K</kbd></button><button class="icon-button" data-action="notifications" aria-label="Buka Proaktif">${icon('bell',18)}${openCount?'<i class="notification-dot"></i>':''}</button><span class="topbar-divider"></span><a href="#chat" class="topbar-chat">${icon('chat',15)}<span>Chat with Data</span></a></div></header><main class="main route-${state.route}" id="main-content" tabindex="-1">${renderPage()}<footer class="page-footer"><span><i class="live-dot"></i>${state.cloud?'Data bisnis':'Data contoh'} · ${state.files.filter(f=>f.status==='Terhubung').length} sumber tersedia</span></footer></main></div>
  </div>`;
  bindPage();
}
function heading(title,description,actions=true) {
  return `<div class="page-heading"><div><h1>${title}</h1></div>${actions?`<div class="heading-actions"><select class="period-select" id="period" aria-label="Periode analisis"><option value="21" ${state.period==='21'?'selected':''}>21 hari terakhir</option><option value="14" ${state.period==='14'?'selected':''}>14 hari terakhir</option><option value="7" ${state.period==='7'?'selected':''}>7 hari terakhir</option></select><button class="btn btn-primary" data-action="upload">${icon('plus',15)}<span>Tambah data</span></button></div>`:''}</div>${dashboardRoutes.includes(state.route)?dashboardTabs():''}`;
}
function demoStrip() {
  return `<div class="demo-strip"><span><i class="live-dot"></i>${state.cloud?'Supabase':'Data contoh'}</span><span class="separator"></span><span>${periodLabel()}</span><span class="separator"></span><button data-action="about">${state.files.filter(f=>f.status==='Terhubung').length} sumber data ${icon('info',12)}</button></div>`;
}
function sparkline(type=0){const lines=['0,20 8,16 16,18 24,10 32,13 40,7 48,10 56,3 64,5','0,18 8,19 16,13 24,15 32,10 40,12 48,6 56,8 64,2','0,8 8,10 16,5 24,12 32,10 40,16 48,13 56,17 64,14','0,21 8,18 16,20 24,11 32,13 40,9 48,12 56,7 64,2'];const line=lines[type%4];return `<svg class="kpi-spark" viewBox="0 0 64 25" aria-hidden="true"><path class="area" d="M${line.replaceAll(' ',' L')} L64,25 L0,25Z"/><path d="M${line.replaceAll(' ',' L')}"/></svg>`;}
function kpis() {
  const m=state.cloud?state.dashboard.metrics:metricSummary(filteredOrders());
  const revenue=m.revenue>=1000000?'Rp '+(m.revenue/1000000).toLocaleString('id-ID',{minimumFractionDigits:1,maximumFractionDigits:1})+' jt':rupiah(m.revenue);
  return `<div class="kpi-grid" aria-label="Metrik bisnis"><article class="kpi"><div class="kpi-label">Total penjualan<button class="icon-button" data-action="metric" data-metric="revenue" aria-label="Definisi dan sumber total penjualan">${icon('info',14)}</button></div><div class="kpi-value" title="${rupiah(m.revenue)}">${revenue}</div><div class="kpi-bottom"><span class="metric-tag">${num(m.units)} unit</span></div></article><article class="kpi"><div class="kpi-label">Pesanan ${icon('sales',16)}</div><div class="kpi-value">${num(m.orders)}<span>pesanan</span></div><div class="kpi-bottom"><span>Rata-rata ${rupiah(m.orders?Math.round(m.revenue/m.orders):0)}</span></div></article><article class="kpi"><div class="kpi-label">Stok tersedia ${icon('box',16)}</div><div class="kpi-value">${num(state.cloud?state.dashboard.inventory.units:products.reduce((v,p)=>v+p.stock,0))}<span>unit</span></div><div class="kpi-bottom"><span>${products.length} SKU di gudang</span><a href="#inventory" class="metric-tag warning">${products.filter(p=>p.stock<p.minimum).length} minimum</a></div></article><article class="kpi"><div class="kpi-label">Dalam produksi ${icon('production',16)}</div><div class="kpi-value">${num(state.cloud?state.dashboard.production.units:production.reduce((v,b)=>v+b.qty,0))}<span>unit</span></div><div class="kpi-bottom"><span>${state.cloud?state.dashboard.production.active:production.length} batch aktif</span><a href="#production" class="metric-tag warning">${production.filter(b=>b.status==='Terlambat').length} terlambat</a></div></article></div>`;
}
function chart(){const rows=filteredOrders();const grouped=new Map();for(const r of rows){if(!grouped.has(r.date))grouped.set(r.date,[]);grouped.get(r.date).push(r);}const entries=state.cloud?state.dashboard.daily.map(d=>({date:d.date,value:state.chart==='revenue'?d.revenue:d.orders})):[...grouped.entries()].sort((a,b)=>a[0].localeCompare(b[0])).map(([date,list])=>({date,value:state.chart==='revenue'?metricSummary(list).revenue:metricSummary(list).orders}));const max=Math.max(1,...entries.map(e=>e.value))*1.22;const W=660,H=220,left=54,right=15,top=15,bottom=35;const x=i=>left+(entries.length<=1?(W-left-right)/2:i/(entries.length-1)*(W-left-right));const y=v=>H-bottom-v/max*(H-top-bottom);const points=entries.map((e,i)=>`${x(i).toFixed(1)},${y(e.value).toFixed(1)}`);const line=points.length?`M${points.join(' L')}`:'';let grids='';for(let i=0;i<4;i++){const v=max/3*i,yy=y(v);grids+=`<line class="grid" x1="${left}" x2="${W-right}" y1="${yy}" y2="${yy}"/><text x="${left-12}" y="${yy+3}" text-anchor="end">${state.chart==='revenue'?'Rp '+short(v):Math.round(v)}</text>`;}let labels='';for(let i=0;i<entries.length;i++)if(i===0||i===entries.length-1||i%Math.max(1,Math.floor(entries.length/5))===0)labels+=`<text x="${x(i)}" y="${H-10}" text-anchor="middle">${dateLabel(entries[i].date)}</text>`;
 return `<section class="panel chart-panel"><div class="panel-head"><div><h2>Penjualan harian</h2></div><button class="panel-action" data-action="metric" data-metric="revenue">Sumber data ${icon('external',13)}</button></div><div class="chart-toolbar"><div class="chart-legend"><span><i class="legend-dot"></i>${state.chart==='revenue'?'Penjualan tercatat':'Pesanan unik'} per hari</span><span>${periodLabel()}</span></div><div class="segmented" role="group" aria-label="Metrik grafik"><button data-chart="revenue" class="${state.chart==='revenue'?'active':''}">Penjualan</button><button data-chart="orders" class="${state.chart==='orders'?'active':''}">Pesanan</button></div></div><div class="chart-wrap"><svg class="sales-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Grafik ${state.chart==='revenue'?'penjualan tercatat':'pesanan'} harian, ${periodLabel()}"><defs><linearGradient id="revenue-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#bf775a" stop-opacity=".16"/><stop offset="100%" stop-color="#bf775a" stop-opacity="0"/></linearGradient></defs>${grids}${line?`<path class="chart-area" d="${line} L${x(entries.length-1)},${H-bottom} L${x(0)},${H-bottom}Z"/><path class="current" d="${line}"/>`:''}${entries.map((e,i)=>`<circle class="chart-point" cx="${x(i)}" cy="${y(e.value)}" r="3" tabindex="0" data-point="${escape(dateLabel(e.date))}" data-value="${state.chart==='revenue'?rupiah(e.value):num(e.value)+' pesanan'}"><title>${dateLabel(e.date)}: ${state.chart==='revenue'?rupiah(e.value):num(e.value)+' pesanan'}</title></circle>`).join('')}${labels}</svg><div class="chart-tooltip hidden"></div></div></section>`;
}

let insights=[
  {id:'stock',icon:'box',title:'Dua produk di bawah stok minimum',description:'Kemeja Senja dan Outer Rimba berada di bawah batas minimum.',link:'Periksa persediaan',route:'inventory',tone:'amber',priority:'Prioritas tinggi',stat:'2 SKU',statLabel:'di bawah batas minimum',evidence:'Kemeja Senja: 18 / 30 unit · Outer Rimba: 12 / 20 unit.',recommendation:'Periksa ketersediaan produksi sebelum menentukan kebutuhan pengisian stok.',source:'stok_gudang_utama.xlsx',question:'Stok perlu diisi?'},
  {id:'late',icon:'clock',title:'Satu batch produksi melewati tenggat',description:'Batch PRD-023 belum selesai sesuai target 20 Oktober.',link:'Lihat produksi',route:'production',tone:'amber',priority:'Perlu ditindaklanjuti',stat:'120 unit',statLabel:'dalam batch yang terlambat',evidence:'PRD-023 · Kemeja Senja · status terakhir: penjahitan.',recommendation:'Konfirmasikan estimasi penyelesaian dengan pemasok. Penyebab keterlambatan belum tercatat.',source:'progres_produksi.xlsx',question:'Produksi terlambat?'},
  {id:'fresh',icon:'data',title:'Dokumen menunggu peninjauan',description:'Faktur pemasok belum disertakan dalam perhitungan.',link:'Tinjau sumber data',route:'sources',tone:'',priority:'Kualitas data',stat:'1 dokumen',statLabel:'menunggu pemeriksaan',evidence:'Faktur pemasok Oktober menunggu peninjauan.',recommendation:'Periksa hasil pengolahan dokumen sebelum menyertakannya dalam perhitungan.',source:'invoice_vendor_oktober.pdf',question:'Dokumen apa yang perlu ditinjau?'}
];
function pendingInsights(){return insights.filter(i=>!state.resolved.includes(i.id));}
function priorityBrief() {
  const active=pendingInsights();
  const copy={stock:{title:'Stok minimum',detail:'Kemeja Senja 18 unit · Outer Rimba 12 unit.'},late:{title:'Produksi terlambat',detail:'PRD-023 · Target 20 Okt · Tahap penjahitan.'},fresh:{title:'Dokumen belum diproses',detail:'Faktur pemasok Oktober menunggu peninjauan.'}};
  return `<section class="priority-brief" aria-labelledby="priority-title"><div class="priority-header"><h2 id="priority-title">${icon('spark',16)}Prioritas <span class="priority-total">${active.length}</span></h2><a href="#insights" class="priority-all">Lihat semua ${icon('arrow',14)}</a></div>${active.length?`<div class="priority-grid">${active.map(i=>`<article class="priority-card" data-priority="${i.id}"><div class="priority-card-top"><h3><span class="priority-icon ${i.id==='fresh'?'neutral':''}">${icon(i.icon,15)}</span>${escape(state.cloud||dashboard.active()?i.title:copy[i.id].title)}</h3><span class="priority-stat">${i.stat}</span></div><p>${escape(state.cloud||dashboard.active()?i.evidence:copy[i.id].detail)}</p><div class="priority-actions"><a href="#${i.route}" class="priority-link">Tinjau ${icon('arrow',12)}</a><button class="priority-ask" data-insight-chat="${i.id}" aria-label="Analisis ${escape(i.title)} di Chat with Data">${icon('chat',13)}</button></div></article>`).join('')}</div>`:`<div class="priority-complete">${icon('check',20)}<span>Semua temuan sudah ditinjau.</span><button class="btn btn-small" data-action="reset-alerts">Tinjau kembali</button></div>`}</section>`;
}
function productThumb(p){return `<span class="product-thumb" style="--swatch:${/^#[0-9a-f]{6}$/i.test(p.color)?p.color:'#ddd5ca'}"><span>${escape(p.initials||p.name.slice(0,2).toUpperCase())}</span></span>`;}
function topProducts(){const grouped=new Map();for(const row of filteredOrders()){const existing=grouped.get(row.sku)||{sku:row.sku,name:row.product,units:0,total:0};existing.units+=row.quantity;existing.total+=row.total;grouped.set(row.sku,existing);}const top=state.cloud?state.dashboard.products.slice(0,4):[...grouped.values()].sort((a,b)=>b.total-a.total).slice(0,4);return `<section class="section-gap"><div class="section-title"><h2>Produk teratas <small>${top.length} produk</small></h2><a class="panel-action" href="#sales">Lihat semua ${icon('arrow',12)}</a></div><div class="panel"><div class="table-scroll"><table class="products-table"><thead><tr><th>PRODUK</th><th>TERJUAL</th><th>PENJUALAN</th><th>STATUS STOK</th><th></th></tr></thead><tbody>${top.map(p=>{const product=products.find(r=>r.sku===p.sku);return `<tr><td><div class="product-cell">${product?productThumb(product):'<span class="product-thumb">'+icon('box')+'</span>'}<span><strong>${escape(p.name)}</strong><small>${escape(p.sku)}</small></span></div></td><td>${num(p.units)} <span class="muted">unit</span></td><td>${rupiah(p.total)}</td><td>${product?badge(product.stock<product.minimum?'Menipis':'Aman',product.stock<product.minimum?'amber':''):badge('Belum dipetakan','neutral')}</td><td><button class="icon-button" data-action="product-source" data-sku="${escape(p.sku)}" aria-label="Sumber penjualan ${escape(p.name)}">${icon('chevron',14)}</button></td></tr>`;}).join('')}</tbody></table></div><div class="table-footer"><span>${periodLabel()}</span><button class="panel-action" data-action="metric" data-metric="revenue">Telusuri angka ${icon('arrow',11)}</button></div></div></section>`;}
function stockMini(){return `<section class="panel"><div class="panel-head"><h2>Kebutuhan pengisian stok</h2>${icon('box',14)}</div><div class="stock-mini">${products.filter(p=>p.stock<p.minimum).map(p=>`<div class="stock-row"><span><strong>${escape(p.name)}</strong><small>${escape(p.variant)}</small></span><span class="stock-value">${p.stock} unit<span>min. ${p.minimum}</span></span></div>`).join('')}</div><a class="source-note" href="#inventory">${icon('arrow',11)}Semua persediaan</a></section>`;}
function productionMini(){return `<section class="panel section-gap"><div class="panel-head"><div><h2>Produksi yang sedang berjalan</h2><p>Progres batch dari pembaruan terakhir.</p></div><a class="panel-action" href="#production">Lihat detail ${icon('arrow',11)}</a></div><div class="production-mini">${production.slice(0,3).map(b=>`<div class="production-item"><strong>${escape(b.name)} <span class="muted">· ${escape(b.id)}</span></strong><small>${b.completed}/${b.qty} unit</small><div class="progress"><span class="${b.status==='Terlambat'?'amber':''}" style="width:${b.completed/b.qty*100}%"></span></div></div>`).join('')}</div></section>`;}
function channelBreakdown() {
  const rows=filteredOrders();const total=metricSummary(rows).revenue;
  const channels=state.cloud?state.dashboard.channels:[...new Set(rows.map(r=>r.channel))].map(name=>({name,total:metricSummary(rows.filter(r=>r.channel===name)).revenue})).sort((a,b)=>b.total-a.total);
  return `<section class="panel channel-panel"><div class="panel-head"><div><h2>Penjualan per kanal</h2></div>${icon('sales',16)}</div><div class="channel-list">${channels.map((c,i)=>`<div class="channel-item"><div class="channel-row"><span><i class="channel-dot color-${i%3}"></i>${escape(c.name)}</span><strong>${Math.round(total?c.total/total*100:0)}%</strong></div><div class="channel-bar"><span class="color-${i%3}" style="width:${total?c.total/total*100:0}%"></span></div><div class="channel-amount">${rupiah(c.total)}</div></div>`).join('')||'<p class="muted">Belum ada transaksi pada periode ini.</p>'}</div><a href="#sales" class="channel-footer">Lihat transaksi ${icon('arrow',13)}</a></section>`;
}
function dashboardQuestion() {
  return `<section class="panel dashboard-question"><div class="question-panel-heading">${icon('chat',19)}<div><h2>Chat with Data</h2></div></div><form id="dashboard-question-form"><label class="sr-only" for="dashboard-question">Pertanyaan untuk Chat with Data</label><div class="dashboard-question-input"><input id="dashboard-question" placeholder="Produk terlaris?" required maxlength="500"><button class="icon-button" type="submit" aria-label="Tanyakan di Chat with Data">${icon('send',17)}</button></div></form><a href="#chat" class="panel-action">Buka chat ${icon('arrow',13)}</a></section>`;
}
function overview() {
  if(dashboard.active())return dashboard.overview();
  return `${heading('Ringkasan bisnis','Pantau penjualan, persediaan, dan produksi Nusa Studio.')}${demoStrip()}${priorityBrief()}${kpis()}<div class="dashboard-grid"><div>${chart()}${topProducts()}</div><div class="side-stack dashboard-side">${channelBreakdown()}${dashboardQuestion()}</div></div>`;
}
function sales(){const m=state.cloud?state.dashboard.metrics:metricSummary(filteredOrders());const all=filteredOrders().filter(r=>(state.filter==='all'||r.channel===state.filter)&&`${r.id} ${r.product} ${r.sku}`.toLowerCase().includes(state.query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));return `${heading('Penjualan','Analisis transaksi berdasarkan kanal dan telusuri sumber datanya.')}${demoStrip()}<div class="small-grid">${chart()}<section class="panel"><div class="panel-head"><div><h2>Komposisi kanal</h2></div>${icon('sales',15)}</div><div style="padding:25px 22px">${[...new Set(filteredOrders().map(r=>r.channel))].map(c=>{const total=metricSummary(filteredOrders().filter(r=>r.channel===c)).revenue;return `<div style="margin-bottom:22px"><div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:10px"><span>${escape(c)}</span><strong style="font-weight:500">${rupiah(total)}</strong></div><div class="progress"><span style="width:${m.revenue?total/m.revenue*100:0}%"></span></div></div>`;}).join('')}</div></section></div><section class="section-gap"><div class="section-title"><h2>Daftar transaksi <small>${all.length} baris</small></h2><button class="panel-action" data-action="export">${icon('download',13)}Ekspor CSV</button></div><div class="toolbar"><div class="search-field">${icon('search',14)}<input class="input" id="table-search" placeholder="Cari pesanan atau produk..." value="${escape(state.query)}" aria-label="Cari transaksi"></div><select class="period-select" id="channel-filter" aria-label="Filter kanal"><option value="all">Semua kanal</option>${[...new Set(state.orders.map(r=>r.channel))].map(c=>`<option ${state.filter===c?'selected':''}>${escape(c)}</option>`).join('')}</select></div><div class="panel table-scroll"><table class="products-table"><thead><tr><th>PESANAN / TANGGAL</th><th>PRODUK</th><th>KANAL</th><th>JUMLAH</th><th>TOTAL</th><th>SUMBER</th></tr></thead><tbody>${all.slice(0,60).map(r=>`<tr><td><strong style="font-weight:500">${escape(r.id)}</strong><small class="muted" style="display:block;margin-top:4px">${dateLabel(r.date)}</small></td><td>${escape(r.product)}<small class="muted" style="display:block;margin-top:4px">${escape(r.sku)}</small></td><td>${escape(r.channel)}</td><td>${num(r.quantity)}</td><td>${rupiah(r.total)}</td><td><button class="icon-button" data-action="order-source" data-id="${escape(r.id)}" data-sku="${escape(r.sku)}" aria-label="Sumber pesanan ${escape(r.id)}">${icon('external',13)}</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty-state"><h3>Tidak ada transaksi yang sesuai.</h3><p>Sesuaikan kata kunci atau pilih kanal lain.</p></div></td></tr>'}</tbody></table></div><div class="table-footer"><span>Menampilkan ${Math.min(60,all.length)} dari ${all.length} baris. Ekspor memuat seluruh hasil filter.</span><span>Semua nilai dalam IDR</span></div></section>`;}
function inventory(){const selected=products.filter(p=>(state.filter!=='low'||p.stock<p.minimum)&&`${p.name} ${p.sku}`.toLowerCase().includes(state.query.toLowerCase()));return `${heading('Persediaan','Pantau stok per SKU dan batas minimum persediaan.',false)}${state.cloud?'':'<details class="data-notice"><summary>Data persediaan · 21 Okt 2026</summary><p>Impor CSV memperbarui penjualan. Persediaan menggunakan data contoh.</p></details>'}<div class="toolbar"><div class="segmented"><button data-filter="all" class="${state.filter!=='low'?'active':''}">Semua produk (${products.length})</button><button data-filter="low" class="${state.filter==='low'?'active':''}">Stok minimum (${products.filter(p=>p.stock<p.minimum).length})</button></div><div class="search-field">${icon('search',14)}<input class="input" id="table-search" placeholder="Cari nama atau SKU..." value="${escape(state.query)}" aria-label="Cari produk"></div></div><div class="panel table-scroll"><table class="products-table"><thead><tr><th>PRODUK / SKU</th><th>VARIAN</th><th>STOK SAAT INI</th><th>BATAS MINIMUM</th><th>STATUS</th><th></th></tr></thead><tbody>${selected.map(p=>`<tr><td><div class="product-cell">${productThumb(p)}<span><strong>${escape(p.name)}</strong><small>${escape(p.sku)}</small></span></div></td><td>${escape(p.variant)}</td><td><div class="stock-bar"><span>${p.stock}</span><div class="progress"><span class="${p.stock<p.minimum?'amber':''}" style="width:${Math.min(100,p.stock/150*100)}%"></span></div></div></td><td>${p.minimum} unit</td><td>${badge(p.stock<p.minimum?'Menipis':'Aman',p.stock<p.minimum?'amber':'')}</td><td><button class="icon-button" data-action="stock-source" data-sku="${escape(p.sku)}" aria-label="Sumber stok ${escape(p.name)}">${icon('external',13)}</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty-state"><h3>Produk tidak ditemukan.</h3></div></td></tr>'}</tbody></table><div class="table-footer"><span>Gudang utama · ${selected.length} SKU</span><span>${icon('link',11)}Data persediaan</span></div></div><div class="small-grid section-gap"><section class="panel" style="padding:23px"><h2>Pengisian stok</h2><a class="panel-action" href="#production">Lihat produksi yang berjalan ${icon('arrow',12)}</a></section><section class="panel" style="padding:23px"><h2>Sumber persediaan</h2><a class="panel-action" href="#sources">Periksa sumber data ${icon('arrow',12)}</a></section></div>`;}
function productionPage(){return `${heading('Produksi','Lihat progres setiap batch dan target penyelesaiannya.',false)}<div class="toolbar"><span class="muted" style="font-size:11px">${production.filter(b=>b.completed<b.qty).length} batch aktif · ${new Set(production.map(b=>b.supplier)).size} pemasok</span><button class="btn" data-action="production-source">${icon('link',13)}Lihat sumber</button></div><div class="production-grid">${production.map(b=>`<article class="batch-card"><div class="batch-card-top"><span>${escape(b.id)} / ${escape(b.supplier)}</span>${badge(b.status,b.status==='Terlambat'?'amber':'')}</div><h2>${escape(b.name)}</h2><p>${escape(b.variant)}</p><div class="stage-track">${['Persiapan','Penjahitan','Penyelesaian','Pemeriksaan mutu'].map((s,i)=>`<span class="stage ${i<=b.stage?'done':''}">${s}</span>`).join('')}</div><div class="batch-meta"><span>KUANTITAS<strong>${b.qty} unit</strong></span><span>TARGET SELESAI<strong>${dateLabel(b.target)} ${b.target.slice(0,4)}</strong></span><span>SELESAI<strong>${Math.round(b.completed/b.qty*100)}%</strong></span></div><div class="progress" style="margin-top:16px"><span class="${b.status==='Terlambat'?'amber':''}" style="width:${b.completed/b.qty*100}%"></span></div></article>`).join('')}</div>${state.cloud?'':'<details class="data-notice section-gap"><summary>Tentang data produksi</summary><p>Data contoh per 21 Oktober 2026.</p></details>'}`;}
function sources(){return `${heading('Sumber Data','Kelola sumber data, tinjau isinya, dan periksa riwayat impor.',false)}<div class="upload-banner">${icon('upload',32)}<div><h2>Tambahkan sumber data</h2><p>CSV, Excel, PDF · Maks. 20 berkas</p></div><button class="btn btn-primary" data-action="upload">${icon('plus',14)}Tambah sumber data</button></div><div class="dashboard-grid"><div><div class="section-title"><h2>Berkas <small>${state.files.length} berkas</small></h2><button class="panel-action" data-action="sample">Unduh contoh CSV ${icon('download',12)}</button></div><div class="panel table-scroll"><table class="products-table"><thead><tr><th>NAMA BERKAS</th><th>DOMAIN</th><th>BARIS</th><th>STATUS</th><th></th></tr></thead><tbody>${state.files.map(f=>`<tr><td><div class="file-name"><span class="file-icon ${f.type==='PDF'?'pdf':''}">${f.type}</span><span><strong>${escape(f.name)}</strong><small>${f.date} · ${f.size}</small></span></div></td><td>${f.domain}</td><td>${num(f.rows)||'—'}</td><td>${badge(f.status,f.status==='Perlu review'?'amber':'')}</td><td><button class="icon-button" data-action="file-detail" data-file="${escape(f.id)}" aria-label="Detail ${escape(f.name)}">${icon('chevron',14)}</button></td></tr>`).join('')}</tbody></table></div><section class="section-gap"><div class="section-title"><h2>Riwayat impor</h2></div><div class="panel">${state.history.length?state.history.slice().reverse().map(h=>`<div class="quality-stat"><span><strong style="font-size:12px;font-weight:500">${escape(h.name)}</strong><small style="display:block;margin-top:7px">${h.added} baru · ${h.updated} diperbarui · ${h.unchanged} identik · ${escape(h.date)}</small></span>${!h.rolledBack&&h.id===state.history.filter(x=>!x.rolledBack).at(-1)?.id?`<button class="btn btn-small btn-danger" data-action="rollback" data-batch="${h.id}">Batalkan impor</button>`:badge(h.rolledBack?'Diurungkan':'Tersimpan',h.rolledBack?'neutral':'')}</div>`).join(''):'<div class="empty-state">'+icon('clock',28)+'<h3>Belum ada riwayat impor</h3><p>Hasil impor akan muncul di sini.</p></div>'}</div></section></div><div><section class="panel"><div class="panel-head"><h2>Kualitas data</h2>${icon('shield',15)}</div><div class="quality-stat"><span>Baris data</span><strong>${num(state.datasets?.length?state.datasets.reduce((n,d)=>n+d.row_count,0):state.orders.length)}</strong></div><div class="quality-stat"><span>Set data</span><strong>${state.datasets?.length||0}</strong></div><div class="quality-stat"><span>Dokumen perlu ditinjau</span><strong style="color:#ac8446">${state.files.filter(f=>f.status!=='Terhubung').length}</strong></div></section></div></div>`;}
function insightsPage() {
  const open=pendingInsights();
  const visible=state.insightFilter==='all'?insights:open;
  return `${heading('Proaktif','Tinjau temuan terkait persediaan, produksi, dan kualitas data.',false)}<div class="proactive-intro"><div>${icon('spark',22)}<span><strong>${open.length} temuan perlu ditinjau</strong><small>${state.cloud?'Data bisnis':'Data contoh'}</small></span></div><a href="#chat" class="btn">${icon('chat',14)}Buka Chat with Data</a></div><div class="toolbar"><div class="segmented" role="group" aria-label="Status temuan"><button data-insight-filter="open" class="${state.insightFilter==='open'?'active':''}" aria-pressed="${state.insightFilter==='open'}">Belum ditinjau (${open.length})</button><button data-insight-filter="all" class="${state.insightFilter==='all'?'active':''}" aria-pressed="${state.insightFilter==='all'}">Semua (${insights.length})</button></div>${state.resolved.length?'<button class="panel-action" data-action="reset-alerts">Tandai semua belum ditinjau</button>':''}</div><div class="proactive-list">${visible.map(i=>`<article class="alert-card proactive-card ${state.resolved.includes(i.id)?'resolved':''}"><span class="alert-symbol">${icon(i.icon,20)}</span><div class="proactive-card-content"><div class="proactive-card-heading"><span class="eyebrow">${i.priority}</span>${badge(state.resolved.includes(i.id)?'Ditinjau':'Perlu perhatian',state.resolved.includes(i.id)?'neutral':'amber')}</div><h2>${escape(i.title)}</h2><p>${escape(i.evidence)}</p><div class="recommendation"><details><summary>Tindak lanjut</summary><p>${escape(i.recommendation)}</p></details></div><small>${icon('link',11)}${escape(i.source)} · data contoh</small><div class="proactive-card-actions"><a class="btn btn-small" href="#${i.route}">${i.link} ${icon('arrow',12)}</a><button class="btn btn-primary btn-small" data-insight-chat="${i.id}">${icon('chat',13)}Analisis</button><button class="panel-action review-action" data-action="resolve" data-alert="${i.id}">${icon('check',12)}${state.resolved.includes(i.id)?'Tandai belum ditinjau':'Sudah ditinjau'}</button></div></div></article>`).join('')||`<section class="panel empty-state">${icon('check',30)}<h3>Semua temuan sudah ditinjau.</h3><p>Pilih Semua temuan untuk melihat kembali data pendukung dan rekomendasi tindak lanjut.</p><button class="btn" data-insight-filter="all">Lihat semua temuan</button></section>`}</div>`;
}
function chatPage() {
  const context=insights.find(i=>i.id===state.chatContext);
  const files=state.cloud?state.files:state.files.filter(f=>f.status==='Terhubung');
  const questions=[['sales','Total penjualan?'],['box','Stok perlu diisi?'],['production','Produksi terlambat?'],['tag','Produk terlaris?']];
  return `${heading('Chat with Data','Ajukan pertanyaan tentang data bisnis dan telusuri sumber jawaban.',false)}<div class="chat-workspace-toolbar"><span class="chat-demo-label"><i class="live-dot"></i>${state.cloud?(state.backend?.aiProvider==='chatgpt'?'Using ChatGPT plan':state.backend?.ai?'OpenRouter':'Analisis berbasis aturan'):'Demo · berbasis aturan'}</span><div class="connection-actions"><button class="btn btn-small" data-action="${state.backend?.chatgpt?'chatgpt-connect':'ai-connect'}">Pengaturan AI</button><button class="btn btn-small" data-action="new-chat">${icon('plus',13)}Percakapan baru</button></div></div><div class="chat-workspace"><section class="chat-main-panel" aria-label="Chat with Data">${context?`<div class="chat-insight-context">${icon('spark',16)}<span><small>KONTEKS TEMUAN PROAKTIF</small><strong>${escape(context.title)}</strong></span><button class="icon-button" data-action="clear-chat-context" aria-label="Hapus konteks proaktif">${icon('close',14)}</button></div>`:''}<div class="chat-content">${state.chat.length?'':`<div class="chat-welcome"><img class="chat-mark" src="./favicon.svg" alt=""><h2>Analisis data Anda</h2><div class="question-grid">${questions.map(([i,q])=>`<button class="question-card" data-question="${q}">${icon(i,18)}<span>${q}</span>${icon('arrow',12)}</button>`).join('')}</div></div>`}${state.chatBusy?'<p class="chat-progress" role="status">Menganalisis…</p>':''}<div class="chat-messages" aria-live="polite" aria-relevant="additions" aria-label="Percakapan data">${state.chat.map((m,n)=>`<div class="message-pair" id="message-${n}"><div class="message-user">${escape(m.question)}</div><div class="message-answer"><img src="./favicon.svg" alt="Laras"><div class="answer-content">${m.answer}<div class="answer-source"><span>${icon('link',11)}${escape(m.source)}</span><button class="panel-action" data-go="${m.route}">Periksa data ${icon('arrow',11)}</button></div></div></div></div>`).join('')}</div></div><div class="chat-composer"><form class="chat-input-form" id="chat-form"><label for="chat-input" class="sr-only">Pertanyaan tentang data bisnis</label><textarea ${state.chatBusy?'disabled':''} id="chat-input" rows="2" placeholder="Ajukan pertanyaan tentang data bisnis Anda…" required maxlength="500" aria-describedby="chat-disclaimer"></textarea><button class="btn btn-primary" ${state.chatBusy?'disabled':''} aria-label="Kirim pertanyaan">${icon('send',17)}</button></form><p class="chat-disclaimer" id="chat-disclaimer">${state.cloud?(state.backend?.ai?'Jawaban AI disertai sumber. Periksa angka penting pada data.':'Angka dihitung dari data bisnis.'):'Mode demo · AI belum terhubung'}</p></div></section><aside class="chat-context-panel" aria-label="Konteks data percakapan"><section><h2>${escape(state.workspaceName)}</h2>${dashboard.active()?dashboard.controls(true):`<label for="period">Periode analisis</label><select class="input" id="period"><option value="21" ${state.period==='21'?'selected':''}>21 hari terakhir</option><option value="14" ${state.period==='14'?'selected':''}>14 hari terakhir</option><option value="7" ${state.period==='7'?'selected':''}>7 hari terakhir</option></select><small>${periodLabel()}</small>`}</section><section><details class="source-disclosure"><summary>Sumber data <span>${files.length}</span></summary>${files.map(f=>`<button class="chat-source" data-action="file-detail" data-file="${escape(f.id)}">${icon('file',15)}<span><strong>${escape(f.name)}</strong><small>${f.domain} · ${num(f.rows)} baris</small></span></button>`).join('')}<a href="#sources" class="panel-action">Kelola sumber ${icon('arrow',12)}</a></details></section><section><div class="chat-context-heading"><h3>Temuan terkait</h3><a href="#insights" aria-label="Lihat semua temuan proaktif">${icon('arrow',13)}</a></div>${pendingInsights().slice(0,2).map(i=>`<button class="context-insight" data-insight-chat="${i.id}">${icon(i.icon,14)}<span>${escape(i.title)}</span>${icon('chevron',11)}</button>`).join('')||'<p class="muted">Semua temuan sudah ditinjau.</p>'}</section></aside></div>`;
}
function settings(){
  return `${heading('Pengaturan','',false)}<div class="settings-layout">
  <section class="panel settings-panel"><h2>Ruang kerja</h2><div class="settings-row"><span>Nama bisnis</span><strong>${escape(state.workspaceName)}</strong></div><div class="settings-row"><span>Mata uang</span><span>IDR</span></div><div class="settings-row"><span>Penyimpanan</span>${badge(state.cloud?'Supabase':'Demo lokal',state.cloud?'':'neutral')}</div></section>
  <section class="panel settings-panel"><h2>Koneksi</h2><div class="settings-row"><span>Backend</span>${badge(state.backend?'Aktif':'Belum tersedia',state.backend?'':'neutral')}</div><div class="settings-row"><span>Supabase</span>${badge(state.cloud?'Terhubung':state.backend?.database?'Perlu disiapkan':'Belum dikonfigurasi',state.cloud?'':'neutral')}</div><div class="settings-row"><span>OpenRouter</span>${badge((state.backend?.aiConnection?.configured??state.backend?.ai)?'Dikonfigurasi':'Belum dikonfigurasi',(state.backend?.aiConnection?.configured??state.backend?.ai)?'':'neutral')}</div>${state.backendError?`<p class="error-box">${escape(state.backendError)}</p>`:''}<div class="connection-actions"><button class="btn btn-primary" data-action="cloud-connect">${state.backend?.cloud?.configured?'Kelola koneksi':'Hubungkan Supabase'}</button><button class="btn" data-action="ai-connect">${state.backend?.aiConnection?.configured?'Kelola OpenRouter':'Hubungkan OpenRouter'}</button><button class="btn" data-action="refresh-cloud">${icon('refresh',13)}Periksa koneksi</button></div><details class="integration-detail"><summary>Detail integrasi</summary><p>Satu proyek Supabase per bisnis. Proyek dan tabel dibuat otomatis saat dokumen diproses.</p><p>CSV dan Excel menjadi data terstruktur. Teks dokumen disimpan beserta sumbernya. OCR dan notifikasi belum tersedia.</p></details></section>
  ${state.backend?.chatgpt?.available?`<section class="panel settings-panel"><h2>ChatGPT</h2><div class="settings-row"><span>Akun</span><strong>${escape(state.backend.chatgpt.account?.email||'Belum terhubung')}</strong></div><div class="settings-row"><span>Model</span><span>${escape(state.backend.chatgpt.account?.model||'Belum dipilih')}</span></div><button class="btn btn-primary" data-action="chatgpt-connect">${state.backend.chatgpt.account?.connected?'Kelola ChatGPT':'Continue with ChatGPT'}</button>${state.backend.chatgpt.notice?`<p class="muted">${escape(state.backend.chatgpt.notice)}</p>`:''}</section>`:''}
  <section class="panel settings-panel"><h2>Pemantauan</h2>${[['daily','Ringkasan harian'],['stock','Peringatan stok'],['production','Pengingat produksi']].map(([key,title])=>`<div class="settings-row"><span>${title}</span><button class="toggle" role="switch" aria-label="${title}" aria-checked="${state.preferences[key]}" data-preference="${key}"></button></div>`).join('')}<small class="muted">Preferensi tersimpan · Pengiriman belum aktif</small></section>
  ${state.cloud?'':`<section class="panel settings-panel"><h2>Data contoh</h2><button class="btn btn-danger" data-action="reset-demo">${icon('refresh',13)}Pulihkan data contoh</button></section>`}</div>`;
}
function renderPage(){return ({overview,sales,inventory,production:productionPage,sources,records:()=>dashboard.records(),insights:insightsPage,chat:chatPage,settings}[state.route]||overview)();}
function bindPage(){dashboard.bind();document.getElementById('dashboard-question-form')?.addEventListener('submit',e=>{e.preventDefault();const question=document.getElementById('dashboard-question').value.trim();if(!question)return;state.chatContext=null;state.pendingQuestion=question;go('chat');});document.getElementById('period')?.addEventListener('change',e=>{if(state.cloud){e.target.disabled=true;syncCloud(e.target.value).catch(error=>{toast(error.message,true);render();});}else{state.period=e.target.value;render();}});document.getElementById('channel-filter')?.addEventListener('change',e=>{state.filter=e.target.value;render();});document.getElementById('table-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;state.query=e.target.value;render();const el=document.getElementById('table-search');el.focus();el.setSelectionRange(pos,pos);});document.getElementById('chat-form')?.addEventListener('submit',e=>{e.preventDefault();answerQuestion(document.getElementById('chat-input').value.trim());});document.getElementById('chat-input')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();document.getElementById('chat-form').requestSubmit();}});document.querySelectorAll('.chart-point').forEach(el=>{const show=()=>{const t=document.querySelector('.chart-tooltip');t.innerHTML=`${escape(el.dataset.point)}<strong>${escape(el.dataset.value)}</strong>`;t.classList.remove('hidden');};el.addEventListener('click',show);el.addEventListener('focus',show);el.addEventListener('mouseenter',show);el.addEventListener('mouseleave',()=>document.querySelector('.chart-tooltip')?.classList.add('hidden'));});}

let previousFocus=null;
function openModal(html,small=false){previousFocus=document.activeElement;state.modal=true;document.getElementById('overlay-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${small?'small':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1">${html}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>document.querySelector('.modal input:not([type=file]),.modal select,.modal .icon-button,.modal button')?.focus(),20);}
function modalHeader(title,description=''){return `<div class="modal-header"><div><h2 id="modal-title">${escape(title)}</h2>${description?`<p>${escape(description)}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Tutup dialog">${icon('close',18)}</button></div>`;}
function closeModal(){uploads?.close();state.modal=null;document.getElementById('overlay-root').innerHTML='';document.body.style.overflow='';previousFocus?.focus();}
let toastTimer;function toast(message,error=false){clearTimeout(toastTimer);document.getElementById('toast-root').innerHTML=`<div class="toast ${error?'error':''}">${icon(error?'warning':'check',16)}<span>${escape(message)}</span></div>`;toastTimer=setTimeout(()=>document.getElementById('toast-root').innerHTML='',5000);}
function about(){if(state.cloud){openModal(`${modalHeader('Laras',state.workspaceName)}<div class="modal-body"><p>Data tersimpan di Supabase. Setiap transaksi menyimpan referensi sumbernya.</p><button class="btn" data-action="close-modal">Tutup</button></div>`,true);return;}openModal(`${modalHeader('Tentang Laras','Analisis penjualan, persediaan, dan produksi dalam satu ruang kerja.')}<div class="modal-body"><p style="font-size:12px;color:#839276">Laras menggunakan data contoh Nusa Studio, bisnis mode dan gaya hidup. Data penjualan CSV dapat diimpor, divalidasi, dan ditelusuri sumbernya. Data disimpan di peramban ini.</p><div class="source-summary"><div>DATA CONTOH<strong>1–21 Oktober 2026</strong></div><div>CAKUPAN<strong>Penjualan, stok, produksi</strong></div></div><div class="callout">Koneksi Supabase, model AI, pemrosesan XLSX/PDF, dan pengiriman notifikasi belum tersedia pada versi demo.</div><button class="btn btn-primary" data-action="close-modal">Tutup ${icon('arrow',13)}</button></div>`,true);}
function showMetric(metric='revenue'){const rows=filteredOrders();const m=metricSummary(rows);openModal(`${modalHeader('Definisi dan sumber penjualan','Definisi dan sumber penjualan pada periode terpilih.')}<div class="modal-body"><div class="source-summary"><div>PENJUALAN TERCATAT<strong style="font-size:23px">${rupiah(m.revenue)}</strong></div><div>PERIODE<strong>${periodLabel()}</strong></div><div>SUMBER TRANSAKSI<strong>${new Set(rows.map(r=>r.source)).size} berkas · ${rows.length} baris</strong></div><div>TINGKAT DATA<strong>Satu baris per ID pesanan + SKU</strong></div></div><div class="source-code">penjualan_tercatat = SUM(total)
total = jumlah × harga_satuan − diskon</div><p class="muted" style="font-size:11px;margin-top:16px">Metrik ini merupakan jumlah total transaksi dari berkas sumber. Nilai belum mencakup rekonsiliasi pembayaran, pajak, dan pengembalian dana sehingga belum merepresentasikan penjualan bersih.</p><div class="mapping-preview"><table class="products-table"><thead><tr><th>BERKAS</th><th>BARIS</th><th>PESANAN</th><th>TOTAL</th></tr></thead><tbody>${rows.slice(-5).reverse().map(r=>`<tr><td>${escape(r.source)}</td><td>${r.row}${r.part?' · '+escape(r.part):''}</td><td>${escape(r.id)}</td><td>${rupiah(r.total)}</td></tr>`).join('')}</tbody></table></div></div><div class="modal-footer"><span>Contoh 5 baris penyusun metrik.</span><button class="btn btn-primary" data-action="go-sales">Lihat transaksi ${icon('arrow',13)}</button></div>`);}
function showSource(kind,sku,id){const p=products.find(p=>p.sku===sku);if(kind==='stock'&&state.cloud){openModal(`${modalHeader('Sumber persediaan',p?.name||sku)}<div class="modal-body"><p>${escape(p?.source||'API')} · baris ${p?.source_row||'—'}</p><p>${p?.stock||0} unit · minimum ${p?.minimum||0}</p></div>`,true);return;}if(kind==='stock'){openModal(`${modalHeader('Sumber saldo persediaan',p?.name||'Data persediaan')}<div class="modal-body"><div class="source-summary"><div>BERKAS ASAL<strong>stok_gudang_utama.xlsx</strong></div><div>LEMBAR KERJA / BARIS<strong>Stok utama / ${products.findIndex(p=>p.sku===sku)+2}</strong></div><div>SKU<strong>${escape(sku)}</strong></div><div>SALDO / BATAS MINIMUM<strong>${p.stock} unit / ${p.minimum} unit</strong></div></div><div class="callout">Saldo berasal dari data persediaan per 21 Oktober 2026. Pergerakan stok belum dihitung pada versi demo.</div></div>`,true);return;}const rows=state.orders.filter(r=>r.sku===sku&&(!id||r.id===id));openModal(`${modalHeader(id?'Sumber transaksi':'Sumber penjualan produk',id||p?.name||sku)}<div class="modal-body"><div class="source-summary"><div>PRODUK<strong>${escape(rows[0]?.product||sku)}</strong></div><div>JUMLAH BARIS<strong>${rows.length}</strong></div></div><div class="mapping-preview"><table class="products-table"><thead><tr><th>BERKAS</th><th>BARIS</th><th>PESANAN</th><th>TOTAL</th></tr></thead><tbody>${rows.slice(-10).map(r=>`<tr><td>${escape(r.source)}</td><td>${r.row}${r.part?' · '+escape(r.part):''}</td><td>${escape(r.id)}</td><td>${rupiah(r.total)}</td></tr>`).join('')}</tbody></table></div><p class="muted" style="font-size:10px;margin-top:15px">${rows.length>10?'Menampilkan 10 baris terakhir. ':''}Nomor baris mengacu pada urutan data CSV, dengan nama kolom pada baris pertama.</p></div>`);}
function showFile(id){const f=state.files.find(f=>f.id===id);if(!f)return;openModal(`${modalHeader(f.name,'Detail sumber data pada ruang kerja demo.')}<div class="modal-body"><div class="source-summary"><div>DOMAIN<strong>${f.domain}</strong></div><div>STATUS<strong>${escape(statusLabel(f.status))}</strong></div><div>JUMLAH BARIS<strong>${num(f.rows)}</strong></div><div>PEMBARUAN<strong>${f.date}</strong></div></div>${f.type==='PDF'?'<div class="callout">Dokumen PDF contoh ini memerlukan peninjauan. Pemrosesan dan pratinjau PDF belum tersedia.</div>':`<div class="callout">${f.id.startsWith('seed')?'Data contoh bawaan untuk demonstrasi aplikasi.':'CSV telah diproses di peramban dan disimpan bersama referensi baris.'}</div>`}<button class="btn" data-action="close-modal">Tutup</button></div>`,true);}
function uploadStart(){state.upload={step:1,error:'',parsed:null,file:null,mapping:null,rows:[]};renderUpload();}
const fieldLabels={id:'ID pesanan *',date:'Tanggal transaksi *',sku:'SKU / kode produk *',product:'Nama produk',quantity:'Jumlah *',unit_price:'Harga satuan',discount:'Diskon',total:'Total transaksi',status:'Status',channel:'Kanal penjualan'};
function renderUpload(){const u=state.upload;if(!u)return;const normalized=u.parsed?normalizeRows(u.parsed,u.mapping,u.file.name):[];u.rows=normalized;const invalid=normalized.filter(r=>r.errors.length);const result=u.remote|| (u.parsed?upsertOrders(state.orders,normalized.filter(r=>!r.errors.length),'preview'):null);let body='';
 if(u.step===1)body=`<div id="upload-error">${u.error?`<div class="error-box">${escape(u.error)}</div>`:''}</div><div class="dropzone" id="dropzone">${icon('upload',32)}<h3>Unggah berkas penjualan</h3><p>Seret berkas CSV ke area ini atau pilih berkas dari perangkat Anda.</p><button class="btn btn-primary" data-action="pick-file">${icon('plus',13)}Pilih berkas CSV</button><input type="file" id="file-input" accept=".csv,text/csv" class="hidden"><small>CSV · Maks. 2 MB · 5.000 baris</small></div><button class="sample-link" data-action="use-sample">Gunakan contoh CSV</button><p class="muted" style="font-size:10px;margin-top:15px">Pemrosesan XLSX, PDF, dan OCR belum tersedia.</p>`;
 if(u.step===2)body=`<div class="callout">${icon('file',13)} ${escape(u.file.name)} · ${u.parsed.rows.length} baris. Petakan kolom berkas ke bidang data yang sesuai. Tanggal mendukung YYYY-MM-DD atau DD/MM/YYYY.</div><div class="mapping-grid">${Object.entries(fieldLabels).map(([key,label])=>`<div class="field-group"><label for="map-${key}">${label}</label><select class="input" id="map-${key}" data-map="${key}"><option value="">${key==='total'?'Hitung: jumlah × harga − diskon':key==='discount'?'Tidak ada (0)':'Tidak dipetakan'}</option>${u.parsed.headers.map((h,i)=>`<option value="${i}" ${u.mapping[key]===String(i)?'selected':''}>${escape(h)}</option>`).join('')}</select></div>`).join('')}</div><div id="validation-summary">${invalid.length?`<div class="error-box">${invalid.length} baris belum valid. ${escape(invalid[0].errors.join('; '))}. Periksa pemetaan kolom atau perbaiki berkas CSV.</div>`:'<div class="callout">'+icon('check',13)+' Seluruh baris lolos validasi awal.</div>'}</div><h3 style="margin-top:17px">Pratinjau data</h3><div class="mapping-preview"><table class="products-table"><thead><tr><th>PESANAN</th><th>TANGGAL</th><th>SKU</th><th>JUMLAH</th><th>TOTAL</th></tr></thead><tbody>${normalized.slice(0,5).map(r=>`<tr><td>${escape(r.id)||'—'}</td><td>${escape(r.date)||'—'}</td><td>${escape(r.sku)||'—'}</td><td>${Number.isFinite(r.quantity)?r.quantity:'—'}</td><td>${Number.isFinite(r.total)?rupiah(r.total):'—'}</td></tr>`).join('')}</tbody></table></div>`;
 if(u.step===3)body=`<div class="callout">${icon('shield',14)} Impor menggunakan kombinasi ID pesanan dan SKU untuk mengenali transaksi. Data identik dilewati; data yang berubah memperbarui transaksi terkait.</div><div class="summary-grid"><div class="summary-card"><strong>${result.added}</strong><span>Transaksi baru</span></div><div class="summary-card"><strong>${result.updated}</strong><span>Diperbarui</span></div><div class="summary-card"><strong>${result.unchanged}</strong><span>Identik, dilewati</span></div></div><div class="source-summary"><div>BERKAS<strong>${escape(u.file.name)}</strong></div><div>PERUBAHAN PENJUALAN<strong>${state.cloud?'Setelah persetujuan':rupiah(metricSummary(result.orders).revenue-metricSummary(state.orders).revenue)}</strong></div></div><p class="muted" style="font-size:11px">Seluruh perubahan diterapkan setelah persetujuan. Data sebelum impor disimpan untuk mendukung pembatalan impor.</p><label class="confirm-label"><input type="checkbox" id="approve-import">Saya telah meninjau dan menyetujui ${state.cloud?'impor data bisnis ini':'perubahan data demo ini'}.</label>`;
 openModal(`${modalHeader(u.step===1?'Tambahkan data':u.step===2?'Tinjau pemetaan kolom':'Konfirmasi impor','Pilih berkas, tinjau pemetaan kolom, lalu setujui impor.')}<div class="modal-body"><div class="steps">${['Pilih berkas','Tinjau kolom','Konfirmasi'].map((s,i)=>`${i?'<span class="step-line"></span>':''}<span class="step ${u.step===i+1?'active':''}"><b>${i+1}</b>${s}</span>`).join('')}</div>${body}</div><div class="modal-footer"><span>${u.step===1?(state.cloud?'Divalidasi di server.':'Berkas diproses di peramban ini.'):u.step===2?'* Kolom wajib dipetakan.':'Tidak ada perubahan sebelum disetujui.'}</span><div class="footer-actions"><button class="btn" data-action="${u.step===1?'close-modal':'upload-back'}">${u.step===1?'Batal':'Kembali'}</button>${u.step>1?`<button class="btn btn-primary" id="upload-next" data-action="${u.step===2?'upload-next':'import-confirm'}" ${u.step===2&&invalid.length?'disabled':''} ${u.step===3?'disabled':''}>${u.step===2?'Lihat ringkasan':'Setujui dan impor'}${icon('arrow',13)}</button>`:''}</div></div>`);
 document.getElementById('file-input')?.addEventListener('change',e=>readFile(e.target.files[0]));const dz=document.getElementById('dropzone');if(dz){dz.addEventListener('dragover',e=>{e.preventDefault();dz.classList.add('dragover');});dz.addEventListener('dragleave',()=>dz.classList.remove('dragover'));dz.addEventListener('drop',e=>{e.preventDefault();readFile(e.dataTransfer.files[0]);});}
 document.querySelectorAll('[data-map]').forEach(el=>el.addEventListener('change',e=>{u.mapping[e.target.dataset.map]=e.target.value;const key=e.target.dataset.map;renderUpload();document.querySelector(`[data-map="${key}"]`)?.focus();}));document.getElementById('approve-import')?.addEventListener('change',e=>document.getElementById('upload-next').disabled=!e.target.checked);
}
async function readFile(file){if(!file)return;if(!file.name.toLowerCase().endsWith('.csv')){state.upload.error='Pilih berkas berformat CSV. Pemrosesan XLSX dan PDF belum tersedia pada versi demo.';renderUpload();return;}if(file.size>2*1024*1024){state.upload.error='Ukuran berkas melebihi batas 2 MB.';renderUpload();return;}try{const text=await file.text();loadCSV(text,file.name,file.size);}catch(e){state.upload.error=e.message||'Berkas tidak dapat dibaca. Pastikan formatnya sesuai dan coba kembali.';renderUpload();}}
function loadCSV(text,name,size){try{const parsed=parseCSV(text);if(parsed.rows.length>5000)throw new Error('Versi demo mendukung maksimal 5.000 baris per impor.');state.upload={...state.upload,step:2,file:{name,size},csv:text,parsed,mapping:detectMapping(parsed.headers),error:''};renderUpload();}catch(e){state.upload.error=e.message;state.upload.step=1;renderUpload();}}
const sampleCSV='order_id,date,sku,product,quantity,unit_price,discount,total,status,channel\nORD-DEMO-2001,2026-10-21,NS-KM-001,Kemeja Senja,3,289000,0,867000,Selesai,Website\nORD-DEMO-2002,2026-10-21,NS-TS-002,Essential Tee,5,149000,0,745000,Selesai,Shopee\nORD-DEMO-2003,2026-10-21,NS-CL-003,Celana Hari,2,329000,58000,600000,Selesai,Tokopedia\nORD-DEMO-2004,2026-10-21,NS-OT-004,Outer Rimba,1,459000,0,459000,Diproses,Website\nORD-DEMO-2005,2026-10-21,NS-KM-005,Kemeja Pagi,4,269000,0,1076000,Selesai,Website';
function confirmImport(){const u=state.upload;if(!u||u.step!==3||!document.getElementById('approve-import')?.checked)return;const rows=normalizeRows(u.parsed,u.mapping,u.file.name);if(rows.some(r=>r.errors.length)){toast('Data belum valid. Periksa pemetaan kolom sebelum melanjutkan.',true);return;}const batch='batch-'+Date.now();const before=state.orders.map(r=>({...r}));const result=upsertOrders(state.orders,rows,batch);const date=new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date());state.orders=result.orders;state.history.push({id:batch,name:u.file.name,date,added:result.added,updated:result.updated,unchanged:result.unchanged,before,rolledBack:false});if(result.added+result.updated>0)state.files.push({id:batch,name:u.file.name,type:'CSV',domain:'Penjualan',rows:rows.length,status:'Terhubung',date,size:Math.max(1,Math.ceil(u.file.size/1024))+' KB'});persist();closeModal();state.upload=null;go('overview');toast(`Impor selesai: ${result.added} baru, ${result.updated} diperbarui, ${result.unchanged} identik dilewati.`);}
function download(content,name){const blob=new Blob([content],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(){const rows=filteredOrders().filter(r=>(state.route!=='sales'||state.filter==='all'||r.channel===state.filter)&&(!state.query||`${r.id} ${r.product} ${r.sku}`.toLowerCase().includes(state.query.toLowerCase())));const headers=['id','date','sku','product','quantity','unit_price','discount','total','status','channel','source','row'];const csvCell=v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};download('\uFEFF'+headers.map(csvCell).join(',')+'\n'+rows.map(r=>headers.map(h=>csvCell(r[h])).join(',')).join('\n'),'laras-penjualan.csv');toast(`${rows.length} baris diekspor.`);}
function answerQuestion(question){if(!question)return;if(state.cloud){answerCloud(question);return;}if(dashboard.active()){const result=dashboard.answerDemo(question);if(result){state.chat.push(cloudMessage(question,result));render();return;}}const q=question.toLowerCase();const m=state.cloud?state.dashboard.metrics:metricSummary(filteredOrders());let answer='',source='',route='sales';if(/dokumen|invoice|review|faktur|tinjau/.test(q)){answer='<h3>Satu dokumen menunggu peninjauan.</h3><p><strong>invoice_vendor_oktober.pdf</strong> belum disertakan dalam perhitungan. Periksa hasil pengolahan dokumen dan pemetaan kolom sebelum menyetujui impor.</p><p style="margin-top:10px">Pemrosesan PDF belum tersedia pada versi demo. Status ini digunakan untuk memperlihatkan alur peninjauan dokumen.</p>';source='invoice_vendor_oktober.pdf · status perlu ditinjau';route='sources';}else if(/stok|restock|persediaan/.test(q)){answer=`<h3>Dua SKU memerlukan peninjauan untuk pengisian stok.</h3><p><strong>Kemeja Senja:</strong> 18 unit, di bawah minimum 30.<br><strong>Outer Rimba:</strong> 12 unit, di bawah minimum 20.</p><p style="margin-top:10px">Saldo ini berasal dari data persediaan per 21 Oktober 2026. Periksa batch produksi sebelum menentukan jumlah pembelian.</p>`;source='stok_gudang_utama.xlsx · 6 SKU';route='inventory';}else if(/produksi|batch|terlambat/.test(q)){answer='<h3>Batch PRD-023 melewati target.</h3><p>Kemeja Senja, 120 unit. Target selesai <strong>20 Oktober 2026</strong>; status terakhir berada pada tahap penjahitan. Berdasarkan tanggal acuan demo 21 Oktober, batch terlambat satu hari.</p><p style="margin-top:10px">Penyebab keterlambatan belum dapat dipastikan karena tidak tercantum dalam berkas sumber.</p>';source='progres_produksi.xlsx · PRD-023';route='production';}else if(/laku|teratas|terjual|produk/.test(q)){const g=new Map();for(const r of filteredOrders()){const v=g.get(r.sku)||{name:r.product,qty:0};v.qty+=r.quantity;g.set(r.sku,v);}const top=[...g.values()].sort((a,b)=>b.qty-a.qty).slice(0,3);answer=`<h3>Produk teratas berdasarkan unit terjual.</h3><p>${top.map((p,i)=>`${i+1}. <strong>${escape(p.name)}</strong> — ${num(p.qty)} unit`).join('<br>')}</p><p style="margin-top:10px">Periode ${periodLabel()}. Jumlah unit dihitung dari total kuantitas penjualan setiap produk.</p>`;source=`${filteredOrders().length} baris penjualan · SUM(quantity)`;}else if(/penjualan|pesanan|omzet|revenue/.test(q)){answer=`<h3>Penjualan tercatat ${rupiah(m.revenue)}.</h3><p>Untuk periode <strong>${periodLabel()}</strong>, tersedia <strong>${num(m.orders)} pesanan</strong> dengan ${num(m.units)} unit terjual.</p><p style="margin-top:10px">Rumus: SUM(total) dari ${filteredOrders().length} baris. Nilai ini belum direkonsiliasi dengan pengembalian dana dan pembayaran.</p>`;source=`${new Set(filteredOrders().map(r=>r.source)).size} berkas penjualan · definisi penjualan tercatat`;}else{answer='<h3>Pertanyaan ini belum didukung dalam demo.</h3><p>Topik yang tersedia mencakup total penjualan, produk terlaris, kebutuhan pengisian stok, dan keterlambatan produksi. Jawaban demo dihitung dengan aturan yang telah ditetapkan dari data di peramban.</p>';source='Mode demo · belum terhubung ke model AI';route='sources';}state.chat.push({question,answer,source,route});render();document.getElementById('chat-input')?.focus();document.querySelector('.chat-input-form')?.scrollIntoView({block:'nearest',behavior:'smooth'});}

function askFromInsight(id) {
  const insight=insights.find(i=>i.id===id);if(!insight)return;
  state.chatContext=id;
  if(state.route==='chat')answerQuestion(insight.question);
  else {state.pendingQuestion=insight.question;go('chat');}
}
function searchModal(){openModal(`${modalHeader('Pencarian ruang kerja')}<div class="modal-body"><div class="search-field" style="max-width:none">${icon('search',16)}<input class="input" id="global-search" placeholder="Cari halaman, produk, atau pesanan..." autocomplete="off" aria-label="Pencarian ruang kerja"></div><div id="search-results" class="search-results"></div></div>`,true);const input=document.getElementById('global-search');input.addEventListener('input',()=>updateSearch(input.value));updateSearch('');input.focus();}
function updateSearch(query){const q=query.toLowerCase();const results=Object.entries(titles).filter(([k,v])=>v.toLowerCase().includes(q)).map(([route,name])=>({name,meta:'Halaman ruang kerja',route}));if(q){for(const p of products.filter(p=>`${p.name} ${p.sku}`.toLowerCase().includes(q)))results.push({name:p.name,meta:p.sku,route:'inventory'});for(const r of state.orders.filter(r=>r.id.toLowerCase().includes(q)).slice(0,5))results.push({name:r.id,meta:r.product,route:'sales'});}document.getElementById('search-results').innerHTML=results.slice(0,10).map(r=>`<button class="search-result" data-search-go="${r.route}">${icon('arrow',15)}<span><strong>${escape(r.name)}</strong><small>${escape(r.meta)}</small></span></button>`).join('')||'<p class="muted" style="padding:15px">Belum ada hasil yang cocok.</p>';}
function go(route){if(location.hash==='#'+route){state.route=route;render();}else location.hash=route;}
function confirmDialog(title,description,action,label){openModal(`${modalHeader(title)}<div class="modal-body"><p class="muted" style="font-size:12px">${description}</p></div><div class="modal-footer"><button class="btn" data-action="close-modal">Batal</button><button class="btn btn-danger" data-action="${action}">${label}</button></div>`,true);}
const dashboard=createAdaptiveDashboard({state,api:apiRequest,document,escape,icon,openModal,closeModal,render,go,orders:()=>state.orders,setInsights:value=>{insights=value;},toast,tabs:dashboardTabs,priorities:priorityBrief});
const uploads=createUploadManager({salesMapping:detectMapping,api:apiRequest,state,openModal,closeModal,icon,escape,toast,syncCloud,initializeBackend,go,document,crypto,enabled:()=>typeof window.fetch==='function',readBytes:async file=>{if(file.arrayBuffer)return new Uint8Array(await file.arrayBuffer());return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(new Uint8Array(reader.result));reader.onerror=()=>reject(new Error('Berkas tidak dapat dibaca.'));reader.readAsArrayBuffer(file);});}});
document.addEventListener('click',e=>{
 const el=e.target.closest('[data-action],[data-go],[data-chart],[data-filter],[data-question],[data-preference],[data-search-go],[data-insight-chat],[data-insight-filter]');if(!el)return;
 if(dashboard.handleClick(el))return;
 if(uploads.handleClick(el))return;
 if(handleBackendAction(el))return;
 if(el.dataset.insightChat){askFromInsight(el.dataset.insightChat);return;}if(el.dataset.insightFilter){state.insightFilter=el.dataset.insightFilter;render();return;}if(el.dataset.go){go(el.dataset.go);return;}if(el.dataset.chart){state.chart=el.dataset.chart;render();return;}if(el.dataset.filter){state.filter=el.dataset.filter;render();return;}if(el.dataset.question){answerQuestion(el.dataset.question);return;}if(el.dataset.preference){const k=el.dataset.preference;state.preferences[k]=!state.preferences[k];persist();render();return;}if(el.dataset.searchGo){closeModal();go(el.dataset.searchGo);return;}
 const action=el.dataset.action;
 if(action==='upload')uploadStart();
 else if(action==='close-modal')closeModal();
 else if(action==='menu'){state.mobile=!state.mobile;render();}
 else if(action==='close-menu'){state.mobile=false;render();}
 else if(action==='about'||action==='workspace')about();
 else if(action==='notifications')go('insights');
 else if(action==='new-chat'){state.chat=[];state.chatContext=null;render();document.getElementById('chat-input')?.focus();}
 else if(action==='clear-chat-context'){state.chatContext=null;render();document.getElementById('chat-input')?.focus();}
 else if(action==='search')searchModal();
 else if(action==='metric')showMetric(el.dataset.metric);
 else if(action==='go-sales'){closeModal();go('sales');}
 else if(action==='product-source')showSource('product',el.dataset.sku);
 else if(action==='order-source')showSource('order',el.dataset.sku,el.dataset.id);
 else if(action==='stock-source')showSource('stock',el.dataset.sku);
 else if(action==='file-detail')showFile(el.dataset.file);
 else if(action==='production-source')showFile('seed-prod');
 else if(action==='pick-file')document.getElementById('file-input').click();
 else if(action==='sample')download(sampleCSV,'contoh_penjualan_laras.csv');
 else if(action==='use-sample')loadCSV(sampleCSV,'pembaruan_penjualan_demo.csv',new Blob([sampleCSV]).size);
 else if(action==='upload-back'){state.upload.step--;renderUpload();}
 else if(action==='upload-next'){const u=state.upload;u.rows=normalizeRows(u.parsed,u.mapping,u.file.name);if(u.rows.some(r=>r.errors.length))return;u.step=3;renderUpload();}
 else if(action==='import-confirm')confirmImport();
 else if(action==='export')exportCSV();
 else if(action==='resolve'){const id=el.dataset.alert;state.resolved=state.resolved.includes(id)?state.resolved.filter(x=>x!==id):[...state.resolved,id];persist();render();}
 else if(action==='reset-alerts'){state.resolved=[];persist();render();}
 else if(action==='rollback'){state.rollback=el.dataset.batch;confirmDialog('Batalkan impor terakhir?','Data transaksi akan dikembalikan ke kondisi sebelum impor ini. Riwayat pembatalan tetap disimpan.','confirm-rollback','Batalkan impor');}
 else if(action==='confirm-rollback'){const h=state.history.find(h=>h.id===state.rollback);if(h&&!h.rolledBack){state.orders=h.before.map(r=>({...r}));h.rolledBack=true;state.files=state.files.filter(f=>f.id!==h.id);persist();closeModal();render();toast('Impor dibatalkan. Riwayat pembatalan tetap tersimpan.');}}
 else if(action==='reset-demo')confirmDialog('Pulihkan data contoh?','Data impor, preferensi, dan riwayat pada peramban ini akan dihapus. Data contoh bawaan akan dipulihkan.','confirm-reset','Pulihkan data contoh');
 else if(action==='confirm-reset'){localStorage.removeItem(storageKey);location.hash='overview';location.reload();}
 else if(action==='connection-info')openModal(`${modalHeader('Basis data khusus bisnis')}<div class="modal-body"><p class="muted" style="font-size:12px">Rencana alur koneksi Supabase:</p><div class="source-code" style="margin:17px 0">1. Otorisasi akun Supabase\n2. Pilih organisasi tujuan\n3. Buat atau hubungkan proyek bisnis\n4. Tinjau struktur data\n5. Setujui perubahan struktur dan impor data</div><p class="muted" style="font-size:11px">Koneksi Supabase belum tersedia pada versi demo. Kredensial tidak dikirim dan proyek belum dibuat.</p></div>`,true);
});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchModal();}if(e.key==='Escape'){if(state.modal)closeModal();else if(state.mobile){state.mobile=false;render();}}if(e.key==='Tab'&&state.modal){const nodes=[...document.querySelectorAll('.modal button:not(:disabled),.modal input:not([type=file]),.modal select,.modal a[href]')].filter(n=>n.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{const route=location.hash.replace('#','');state.route=Object.hasOwn(titles,route)?route:'overview';state.query='';state.filter='all';state.mobile=false;render();if(state.route==='chat'&&state.pendingQuestion){const question=state.pendingQuestion;state.pendingQuestion=null;answerQuestion(question);}window.scrollTo(0,0);});
if(!Object.hasOwn(titles,state.route))state.route='overview';render();
if(typeof window.fetch==='function')initializeBackend();

// Server-backed operations are explicit; demo data is never uploaded automatically.
let syncSequence=0;
async function syncCloud(period=state.period){
  const sequence=++syncSequence;
  let data;try{data=await apiRequest('/workspace?days='+encodeURIComponent(period)+'&'+(state.cloud?dashboard.query():''));}catch(error){if(['DATASET_NOT_FOUND','NOT_FOUND'].includes(error.code)){state.adaptiveView={};data=await apiRequest('/workspace?days='+encodeURIComponent(period));}else throw error;}
  if(sequence!==syncSequence)return;
  state.cloud=true;state.period=String(period);state.backendError='';state.workspaceName=data.workspace.name;
  state.orders=data.orders;state.files=data.files.map(f=>({...f,date:new Date(f.date).toLocaleDateString('id-ID'),size:Math.ceil(f.size/1024)+' KB'}));
  state.history=data.history.map(h=>({...h,date:new Date(h.date).toLocaleString('id-ID')}));
  state.preferences=data.workspace.preferences;state.dashboard=data.dashboard;state.revision=data.workspace.revision;
  products=data.products;production=data.production;insights=data.insights;
  state.resolved=insights.filter(i=>data.reviewed.includes(i.fingerprint)).map(i=>i.id);dashboard.onBootstrap(data);
  render();
}
async function initializeBackend(){
  try{
    state.backend=await apiRequest('/status');
    if(state.backend.database&&(!state.backend.cloud||state.backend.cloud.phase==='ready')){await syncCloud();}
    else{if(state.cloud)throw new Error('Koneksi Supabase belum siap.');dashboard.initDemo();render();}
  }catch(error){state.backendError=error.message;if(!state.cloud)dashboard.initDemo();render();}
}
function cloudMessage(question,result){
  return {question,answer:`<h3>${escape(result.title)}</h3><p>${result.lines.map(escape).join('<br>')}</p>${result.verifiedFacts?`<details class="verified-facts"><summary>Perhitungan terverifikasi</summary><p>${escape(result.verifiedFacts.title)}<br>${result.verifiedFacts.lines.map(escape).join('<br>')}</p></details>`:''}${result.notice?`<p class="muted">${escape(result.notice)}</p>`:''}`,source:result.sources.map(s=>s.name+(s.row?' · baris '+s.row:s.part?' · '+s.part:'')).join(', ')||'Data bisnis',route:result.route};
}
async function answerCloud(question){
  if(state.chatBusy)return;state.chatBusy=true;render();
  try{
    const result=await apiRequest('/chat',{method:'POST',key:crypto.randomUUID(),body:{question,days:Number(state.period),datasetId:state.adaptive?.dataset.id,adaptiveDays:state.adaptive?.selection.days,metricKey:state.adaptive?.selection.metricKey,dateKey:state.adaptive?.selection.dateKey,groupKey:state.adaptive?.selection.groupKey}});
    state.chat.push(cloudMessage(question,result));
  }catch(error){toast(error.message,true);}
  finally{state.chatBusy=false;render();document.getElementById('chat-input')?.focus();}
}
async function previewCloud(){
  const u=state.upload;if(!u||u.pending)return;u.pending=true;
  const button=document.getElementById('upload-next');if(button)button.disabled=true;
  try{
    u.remote=await apiRequest('/imports/preview',{method:'POST',key:crypto.randomUUID(),body:{name:u.file.name,csv:u.csv,mapping:u.mapping}});
    u.step=3;renderUpload();
  }catch(error){toast(error.message+(error.details?.errors?.[0]?' Baris '+error.details.errors[0].row+': '+error.details.errors[0].errors.join('; '):''),true);}
  finally{u.pending=false;if(u.step===2&&button)button.disabled=false;}
}
async function commitCloud(){
  const u=state.upload;if(!u?.remote||u.pending||!document.getElementById('approve-import')?.checked)return;
  u.pending=true;document.getElementById('upload-next').disabled=true;
  try{const result=await apiRequest(`/imports/${u.remote.id}/commit`,{method:'POST',body:{approved:true}});closeModal();state.upload=null;await syncCloud();go('overview');toast(`Impor selesai: ${result.added} baru, ${result.updated} diperbarui.`);}
  catch(error){toast(error.message,true);u.pending=false;const button=document.getElementById('upload-next');if(button)button.disabled=false;}
}
function handleBackendAction(el){
  const action=el.dataset.action;
  if(action==='refresh-cloud'||action==='setup-cloud'){
    el.disabled=true;
    (async()=>{try{if(action==='setup-cloud')await apiRequest('/setup',{method:'POST',body:{}});await initializeBackend();}catch(error){state.backendError=error.message;render();}finally{el.disabled=false;}})();return true;
  }
  if(!state.cloud)return false;
  if(action==='upload-next'){previewCloud();return true;}
  if(action==='import-confirm'){commitCloud();return true;}
  let task;
  if(el.dataset.preference){const key=el.dataset.preference;task=()=>apiRequest('/preferences',{method:'PATCH',body:{preferences:{[key]:!state.preferences[key]}}});}
  else if(action==='resolve'){const finding=insights.find(i=>i.id===el.dataset.alert);task=()=>apiRequest('/insights/review',{method:'POST',body:{fingerprint:finding.fingerprint,datasetId:state.adaptive?.dataset.id,reviewed:!state.resolved.includes(finding.id)}});}
  else if(action==='reset-alerts'){task=async()=>{for(const finding of insights.filter(i=>state.resolved.includes(i.id)))await apiRequest('/insights/review',{method:'POST',body:{fingerprint:finding.fingerprint,datasetId:state.adaptive?.dataset.id,reviewed:false}});};}
  else if(action==='confirm-rollback'){task=async()=>{await apiRequest(`/imports/${state.rollback}/rollback`,{method:'POST',body:{}});closeModal();};}
  else if(action==='production-source'){openModal(`${modalHeader('Sumber produksi')}<div class="modal-body">${production.map(p=>`<p>${escape(p.id)} · ${escape(p.source||'API')}</p>`).join('')}</div>`,true);return true;}
  if(!task)return false;
  el.disabled=true;
  (async()=>{try{await task();await syncCloud();}catch(error){toast(error.message,true);}finally{el.disabled=false;}})();return true;
}
